mapper.update:
update ry_business.ry_rental_order_channel
set channel_name = #{name}, status = #{status}, sort_no = #{sortNo},
    update_by = #{operatorId}, update_time = now(), remark = #{remark}
where tenant_id = #{tenantId} and member_id = #{memberId} and channel_id = #{channelId}
  and scope_type = 2 and is_delete = 0

update ry_business.ry_rental_inventory_balance
set on_hand_qty = #{quantity}, version = version + 1, update_by = #{operator}, update_time = now(), remark = #{remark}
where tenant_id = #{tenantId} and member_id = #{memberId} and balance_id = #{balanceId} and is_delete = 0

mapper.select:
select unit_id as unitId, product_id as productId, warehouse_id as warehouseId, unit_code as unitCode, unit_status as unitStatus, version from ry_business.ry_rental_inventory_unit where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0
and unit_id = #{unitId} and unit_code = #{unitCode}
limit 1 for update

select sn_id as snId, product_id as productId, warehouse_id as warehouseId, sn_code as snCode, asset_status as assetStatus from ry_business.ry_rental_asset_sn where tenant_id = #{tenantId} and member_id = #{memberId} and is_delete = 0
and sn_id = #{snId} and sn_code = #{snCode}
limit 1 for update

select p.protocol_id as protocolId, p.protocol_key as protocolKey, p.version_no as versionNo, p.protocol_title as protocolTitle, p.protocol_content as protocolContent, p.content_hash as contentHash, p.protocol_status as protocolStatus, date_format(p.effective_time, '%Y-%m-%d %H:%i:%s') as effectiveTime, coalesce(group_concat(distinct ps.scope_type order by ps.scope_type), '1') as scopeTypes from ry_business.ry_rental_protocol p left join ry_business.ry_rental_protocol_scope ps on ps.protocol_id = p.protocol_id and ps.is_delete = 0 where p.is_delete = 0 and p.protocol_key = #{protocolKey}
and p.protocol_status = 1 and (p.effective_time is null or p.effective_time <= now()) and ps.scope_type = #{scopeType} and p.protocol_id = ( select current_protocol.protocol_id from ry_business.ry_rental_protocol current_protocol inner join ry_business.ry_rental_protocol_scope current_scope on current_scope.protocol_id = current_protocol.protocol_id and current_scope.scope_type = #{scopeType} and current_scope.is_delete = 0 where current_protocol.protocol_key = p.protocol_key and current_protocol.protocol_status = 1 and (current_protocol.effective_time is null or current_protocol.effective_time <= now()) and current_protocol.is_delete = 0 order by current_protocol.version_no desc limit 1 )
group by p.protocol_id, p.protocol_key, p.version_no, p.protocol_title, p.protocol_content, p.content_hash, p.protocol_status, p.effective_time order by p.protocol_key, p.version_no desc
